    [13] = {code = "Windurst 4-1", s = {["|2"] = "To flag the Mission, head to the Windurstian Embassy in Jeuno, Ru'Lude Gardens (I-9) and speak with clerk Pakh Jatalfih.", ["|3"] = "Click on the door to the Audience Chamber in Ru'Lude Gardens (H-6) for a cutscene and the Letter to Aldo.", ["|4"] = "Speak to Aldo in Lower Jeuno, in the back of the Neptune's Spire Tenshodo H.Q. for a cutscene and the Silver bell.", ["|5"] = "Obtain the 3 Magicite Key Items.", ["|6"] = "Click the Audience Chamber in Ru'Lude Gardens (H-5) after obtaining all 3 Magicites for a cutscene and your reward (either an Airship Pass,", ["|7"] = "Return to Pakh Jatalfih in the Windurstian Embassy to complete the mission, receive 10,000 Gil and Message to Jeuno (Windurst)."}},
    [14] = {code = "Windurst 5-1", s = {["|2"] = "Click the Door: Vestal Chamber at the top of the Tower to start the Mission and to receive New Fei'Yin seal.", ["|3"] = "Go to Fei'Yin (located in the northeast corner of Beaucedine Glacier) for a cutscene with Zeid.", ["|4"] = "You only need to kill the Archlich to win.", ["|5"] = "You will be facing Archlich Taber'quoan.", ["|6"] = "When you win, you'll be given another cutscene and receive Burnt seal.", ["|7"] = "Check the Door: Vestal Chamber at the top to complete the Mission."}},
    [15] = {code = "Windurst 5-2", s = {["|1"] = "Head to the top of the Heavens Tower in Windurst Walls HP #1 and click the Door: Vestal Chamber.", ["|10"] = "Head up the stairs and you will be on the second \"level\".", ["|11"] = "Next, get to the top left part of the map and walk back down the set of stairs and you'll be back on the first \"level\".", ["|12"] = "Work your way into the center of the map from here and you will be in an outdoor courtyard.", ["|13"] = "Inside, walk out of the hallway and turn right.", ["|14"] = "Once on the second level, you will be overlooking a room below.", ["|15"] = "Follow the teleporters four times until you reach a new map.", ["|16"] = "The Shadow Lord has 2 forms.", ["|17"] = "While immune to magic, he will use Dark Nova (AOE Darkness damage) and can cast Black Magic.", ["|18"] = "During physical immunity, he can use a variety of TP attacks, including Giga Slash, Kick Back and Umbra Smash.", ["|19"] = "Defeating the first form will get you a cutscene.", ["|2"] = "Castle Zvahl Keep Home Point #1 is fastest way.", ["|20"] = "The second form will only use AoE attacks, but has less HP (approximately 4,000 HP).", ["|3"] = "After you clear the BCNM, you'll get another cutscene.", ["|4"] = "Zone into Heavens Tower for a brief cutscene.", ["|5"] = "Click the Door: Vestal Chamber for a final cutscene and your reward: Rank 6 and 20,000 Gil.", ["|6"] = "Head for Xarcabard.", ["|7"] = "Enter Castle Zvahl Baileys, follow the one-way path until you come to the first intersection.", ["|8"] = "Turn left and follow the right wall until you reach the next map.", ["|9"] = "On the next map, turn right and head all the way to the top right corner of the map."}},
