    [17] = {code = "Windurst 6-2", s = {["|1"] = "Select the Door: Vestal Chamber at the top of Heavens Tower for a cutscene.", ["|10"] = "Starting from the main entrance on Map 1, go through the first Brass Door (I-8) by turning the correct lever and go upstairs at point A.", ["|11"] = "You'll now be on Map 2.", ["|12"] = "Go upstairs at point G and you'll be on Map 3.", ["|13"] = "Open the the large Brass Door by interacting with the unlit Torch in one of the four corner rooms.", ["|14"] = "Next, you will need to crack the passwords to the Brass Statue to unlock the trapdoor.", ["|15"] = "After the fall, proceed to a smaller Brass Door on the platform, which is past one Yagudo High Priest in this area.", ["|16"] = "Trade the Judgment Key to the Brass Door.", ["|17"] = "Speak to Kaa Toru the Just inside the door to obtain the Holy One's oath and an Ashura Necklace.", ["|2"] = "You will have to proceed to Balga's Dais located in Giddeus, and clear the BCNM \"Saintly Invitation\".", ["|3"] = "Inside are 4 NM Yagudo.", ["|4"] = "The Yagudo may be slept.", ["|5"] = "It is recommended to fight in the order of WHM > SMN > SAM > NIN.", ["|6"] = "It may be useful to pull the WHM out of AoE range, so that it does not wake the others up with Benediction.", ["|7"] = "Trio of 75WHM/NIN 75RDM/BLM 75BLM/WHM can win with relative ease.", ["|8"] = "Once you win the BCNM, proceed to Castle Oztroja located in Meriphataud Mountains.", ["|9"] = "You will need to reach the Brass Door located on the top floor of the Castle (Map 4, H-5)."}},
